import { trackEmissions } from "@bitwarden/common/../spec/utils";
import { mock, MockProxy } from "jest-mock-extended";

import { LogService } from "@bitwarden/logging";

import { mockPorts } from "../../../spec/mock-port.spec-util";

import { BackgroundMemoryStorageService } from "./background-memory-storage.service";
import { ForegroundMemoryStorageService } from "./foreground-memory-storage.service";

describe("foreground background memory storage interaction", () => {
  let foreground: ForegroundMemoryStorageService;
  let background: BackgroundMemoryStorageService;
  let logService: MockProxy<LogService>;

  beforeEach(() => {
    mockPorts();
    logService = mock();

    background = new BackgroundMemoryStorageService(logService);
    foreground = new ForegroundMemoryStorageService();
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  test.each(["has", "get"])(
    "background should respond with the correct value for %s",
    async (action: "get" | "has") => {
      const key = "key";
      const value = "value";
      background[action] = jest.fn().mockResolvedValue(value);

      const result = await foreground[action](key);
      expect(result).toEqual(value);
    },
  );

  test("background should call save from foreground", async () => {
    const key = "key";
    const value = "value";
    const actionSpy = jest.spyOn(background, "save");
    await foreground.save(key, value);

    expect(actionSpy).toHaveBeenCalledWith(key, value);
  });

  test("background should call remove from foreground", async () => {
    const key = "key";
    const actionSpy = jest.spyOn(background, "remove");
    await foreground.remove(key);

    expect(actionSpy).toHaveBeenCalledWith(key);
  });

  test("background updates push to foreground", async () => {
    const key = "key";
    const value = "value";
    const updateType = "save";
    const emissions = trackEmissions(foreground.updates$);
    await background.save(key, value);

    expect(emissions).toEqual([{ key, updateType }]);
  });

  test("background should message only the requesting foreground", async () => {
    const secondForeground = new ForegroundMemoryStorageService();
    const secondPort = secondForeground["_port"];
    const secondPost = secondPort.postMessage as jest.Mock;
    secondPost.mockClear();

    const key = "key";
    await foreground.get(key);

    expect(secondPost).not.toHaveBeenCalled();
  });
});

import AbstractChromeStorageService, {
  objToStore,
  serializationIndicator,
} from "./abstract-chrome-storage-api.service";

class TestChromeStorageApiService extends AbstractChromeStorageService {}

describe("objectToStore", () => {
  it("converts an object to a tagged string", () => {
    const obj = { key: "value" };
    const result = objToStore(obj);
    expect(result).toEqual({
      [serializationIndicator]: true,
      value: JSON.stringify(obj),
    });
  });

  it("converts a set to an array prior to serialization", () => {
    const obj = new Set(["value"]);
    const result = objToStore(obj);
    expect(result).toEqual({
      [serializationIndicator]: true,
      value: JSON.stringify(Array.from(obj)),
    });
  });

  it("does nothing to null", () => {
    expect(objToStore(null)).toEqual(null);
  });
});

describe("ChromeStorageApiService", () => {
  let service: TestChromeStorageApiService;
  let store: Record<any, any>;

  beforeEach(() => {
    store = {};

    service = new TestChromeStorageApiService(chrome.storage.local);
  });

  describe("save", () => {
    let setMock: jest.Mock;

    beforeEach(() => {
      // setup save
      setMock = chrome.storage.local.set as jest.Mock;
      setMock.mockImplementation((data, callback) => {
        Object.assign(store, data);
        callback();
      });
    });

    afterEach(() => {
      (chrome.runtime.lastError as any) = undefined;
    });

    it("uses `objToStore` to prepare a value for set", async () => {
      const key = "key";
      const value = { key: "value" };
      await service.save(key, value);
      expect(setMock).toHaveBeenCalledWith(
        {
          [key]: objToStore(value),
        },
        expect.any(Function),
      );
    });

    it("removes the key when the value is null", async () => {
      const removeMock = chrome.storage.local.remove as jest.Mock;
      removeMock.mockImplementation((key, callback) => {
        delete store[key];
        callback();
      });
      const key = "key";
      await service.save(key, null);
      expect(removeMock).toHaveBeenCalledWith(key, expect.any(Function));
    });

    it("translates chrome.runtime.lastError to promise rejection", async () => {
      setMock.mockImplementation((data, callback) => {
        (chrome.runtime.lastError as any) = new Error("Test Error");
        callback();
      });

      await expect(async () => await service.save("test", {})).rejects.toThrow("Test Error");
    });
  });

  describe("get", () => {
    let getMock: jest.Mock;
    const key = "key";

    beforeEach(() => {
      // setup get
      getMock = chrome.storage.local.get as jest.Mock;
      getMock.mockImplementation((key, callback) => {
        callback({ [key]: store[key] });
      });
    });

    afterEach(() => {
      (chrome.runtime.lastError as any) = undefined;
    });

    it("returns a stored value when it is serialized", async () => {
      const value = { key: "value" };
      store[key] = objToStore(value);
      const result = await service.get(key);
      expect(result).toEqual(value);
    });

    it("returns a stored value when it is not serialized", async () => {
      const value = "value";
      store[key] = value;
      const result = await service.get(key);
      expect(result).toEqual(value);
    });

    it("returns null when the key does not exist", async () => {
      const result = await service.get("key");
      expect(result).toBeNull();
    });

    it("returns null when the stored object is null", async () => {
      store[key] = null;

      const result = await service.get(key);
      expect(result).toBeNull();
    });

    it("translates chrome.runtime.lastError to promise rejection", async () => {
      getMock.mockImplementation((key, callback) => {
        (chrome.runtime.lastError as any) = new Error("Test Error");
        callback();
        (chrome.runtime.lastError as any) = undefined;
      });

      await expect(async () => await service.get("test")).rejects.toThrow("Test Error");
    });
  });
});

import {
  createAssertCredentialResultMock,
  createCreateCredentialResultMock,
  createCredentialCreationOptionsMock,
  createCredentialRequestOptionsMock,
  setupMockedWebAuthnSupport,
} from "../../../autofill/spec/fido2-testing-utils";
import { WebauthnUtils } from "../utils/webauthn-utils";

import { MessageTypes } from "./messaging/message";
import { Messenger } from "./messaging/messenger";

const originalGlobalThis = globalThis;
const mockGlobalThisDocument = {
  ...originalGlobalThis.document,
  contentType: "text/html",
  location: {
    ...originalGlobalThis.document.location,
    href: "https://bitwarden.com",
    origin: "https://bitwarden.com",
    hostname: "bitwarden.com",
    protocol: "https:",
  },
};

let messenger: Messenger;
jest.mock("./messaging/messenger", () => {
  return {
    Messenger: class extends jest.requireActual("./messaging/messenger").Messenger {
      static forDOMCommunication: any = jest.fn((context) => {
        const windowOrigin = context.location.origin;

        messenger = new Messenger({
          postMessage: (message, port) => context.postMessage(message, windowOrigin, [port]),
          addEventListener: (listener) => context.addEventListener("message", listener),
          removeEventListener: (listener) => context.removeEventListener("message", listener),
        });
        messenger.destroy = jest.fn();
        return messenger;
      });
    },
  };
});
jest.mock("../utils/webauthn-utils");
jest.mock("../../../autofill/utils", () => ({
  currentlyInSandboxedIframe: jest.fn(() => false),
}));

describe("Fido2 page script with native WebAuthn support", () => {
  (jest.spyOn(globalThis, "document", "get") as jest.Mock).mockImplementation(
    () => mockGlobalThisDocument,
  );

  const mockCredentialCreationOptions = createCredentialCreationOptionsMock();
  const mockCreateCredentialsResult = createCreateCredentialResultMock();
  const mockCredentialRequestOptions = createCredentialRequestOptionsMock();
  const mockCredentialAssertResult = createAssertCredentialResultMock();
  setupMockedWebAuthnSupport();

  beforeAll(() => {
    // FIXME: Remove when updating file. Eslint update
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    require("./fido2-page-script");
  });

  afterEach(() => {
    jest.resetModules();
  });

  afterAll(() => {
    jest.clearAllMocks();
  });

  describe("creating WebAuthn credentials", () => {
    beforeEach(() => {
      messenger.request = jest.fn().mockResolvedValue({
        type: MessageTypes.CredentialCreationResponse,
        result: mockCreateCredentialsResult,
      });
    });

    it("falls back to the default browser credentials API if an error occurs", async () => {
      window.top.document.hasFocus = jest.fn().mockReturnValue(true);
      messenger.request = jest.fn().mockRejectedValue({ fallbackRequested: true });

      try {
        await navigator.credentials.create(mockCredentialCreationOptions);
        expect("This will fail the test").toBe(true);
      } catch {
        expect(WebauthnUtils.mapCredentialRegistrationResult).not.toHaveBeenCalled();
      }
    });

    it("creates and returns a WebAuthn credential when the navigator API is called to create credentials", async () => {
      await navigator.credentials.create(mockCredentialCreationOptions);

      expect(WebauthnUtils.mapCredentialCreationOptions).toHaveBeenCalledWith(
        mockCredentialCreationOptions,
        true,
      );
      expect(WebauthnUtils.mapCredentialRegistrationResult).toHaveBeenCalledWith(
        mockCreateCredentialsResult,
      );
    });
  });

  describe("get WebAuthn credentials", () => {
    beforeEach(() => {
      messenger.request = jest.fn().mockResolvedValue({
        type: MessageTypes.CredentialGetResponse,
        result: mockCredentialAssertResult,
      });
    });

    it("falls back to the default browser credentials API when an error occurs", async () => {
      window.top.document.hasFocus = jest.fn().mockReturnValue(true);
      messenger.request = jest.fn().mockRejectedValue({ fallbackRequested: true });

      const returnValue = await navigator.credentials.get(mockCredentialRequestOptions);

      expect(returnValue).toBeDefined();
      expect(WebauthnUtils.mapCredentialAssertResult).not.toHaveBeenCalled();
    });

    it("gets and returns the WebAuthn credentials", async () => {
      await navigator.credentials.get(mockCredentialRequestOptions);

      expect(WebauthnUtils.mapCredentialRequestOptions).toHaveBeenCalledWith(
        mockCredentialRequestOptions,
        true,
      );
      expect(WebauthnUtils.mapCredentialAssertResult).toHaveBeenCalledWith(
        mockCredentialAssertResult,
      );
    });

    it("initiates a conditional mediated webauth request", async () => {
      mockCredentialRequestOptions.mediation = "conditional";
      mockCredentialRequestOptions.signal = new AbortController().signal;

      await navigator.credentials.get(mockCredentialRequestOptions);

      expect(WebauthnUtils.mapCredentialAssertResult).toHaveBeenCalledWith(
        mockCredentialAssertResult,
      );
    });
  });

  describe("DOMException rehydration across the messenger boundary", () => {
    // Earlier tests mutate `mockCredentialRequestOptions.mediation`; the conditional
    // mediation path swallows rejections, so reset to a non-conditional value here.
    beforeEach(() => {
      mockCredentialRequestOptions.mediation = "optional";
      mockCredentialRequestOptions.signal = undefined;
    });

    it("rehydrates a serialized NotAllowedError rejection into a real DOMException on create", async () => {
      // The messenger reconstructs cross-world errors as plain Error instances
      // populated via Object.assign — `instanceof DOMException` is lost. The page
      // script should restore it so RPs see what the native API would throw.
      const serializedRejection = Object.assign(new Error(), {
        name: "NotAllowedError",
        message: "The 'publickey-credentials-create' feature is not enabled in this document.",
      });
      messenger.request = jest.fn().mockRejectedValue(serializedRejection);

      await expect(
        navigator.credentials.create(mockCredentialCreationOptions),
      ).rejects.toBeInstanceOf(DOMException);
    });

    it("rehydrates a serialized NotAllowedError rejection into a real DOMException on get", async () => {
      const serializedRejection = Object.assign(new Error(), {
        name: "NotAllowedError",
        message: "The 'publickey-credentials-get' feature is not enabled in this document.",
      });
      messenger.request = jest.fn().mockRejectedValue(serializedRejection);

      await expect(navigator.credentials.get(mockCredentialRequestOptions)).rejects.toBeInstanceOf(
        DOMException,
      );
    });

    it("does not touch rejections with other names", async () => {
      const otherError = Object.assign(new Error(), {
        name: "InvalidStateError",
        message: "Something else went wrong.",
      });
      messenger.request = jest.fn().mockRejectedValue(otherError);

      await expect(navigator.credentials.get(mockCredentialRequestOptions)).rejects.toBe(
        otherError,
      );
    });
  });

  describe("destroy", () => {
    it("should destroy the message listener when receiving a disconnect request", async () => {
      jest.spyOn(globalThis.top, "removeEventListener");
      const SENDER = "bitwarden-webauthn";
      void messenger.handler({ type: MessageTypes.DisconnectRequest, SENDER, senderId: "1" });

      expect(globalThis.top.removeEventListener).toHaveBeenCalledWith("focus", undefined);
      expect(messenger.destroy).toHaveBeenCalled();
    });
  });

  describe("content script execution", () => {
    beforeEach(() => {
      jest.clearAllMocks();
      jest.resetModules();
    });

    it("skips initializing if the document content type is not 'text/html'", () => {
