import { PermissionsPolicyHeaderCacheBackground } from "./permissions-policy-header-cache.background";

type HeadersListener = (details: chrome.webRequest.OnHeadersReceivedDetails) => void;
type TabRemovedListener = (tabId: number) => void;

interface MockEvent<L> {
  addListener: jest.Mock<void, [L, ...unknown[]]>;
  removeListener: jest.Mock<void, [L]>;
}

function createMockEvent<L>(): MockEvent<L> {
  return {
    addListener: jest.fn(),
    removeListener: jest.fn(),
  };
}

function createDetails(
  overrides: Partial<chrome.webRequest.OnHeadersReceivedDetails> = {},
): chrome.webRequest.OnHeadersReceivedDetails {
  return {
    requestId: "req-1",
    url: "https://example.com/",
    method: "GET",
    frameId: 0,
    parentFrameId: -1,
    tabId: 1,
    type: "main_frame",
    timeStamp: 0,
    responseHeaders: [],
    statusLine: "HTTP/1.1 200 OK",
    statusCode: 200,
    ...overrides,
  } as chrome.webRequest.OnHeadersReceivedDetails;
}

describe("PermissionsPolicyHeaderCacheBackground", () => {
  let onHeadersReceived: MockEvent<HeadersListener>;
  let onTabRemoved: MockEvent<TabRemovedListener>;
  let mockWebRequest: typeof chrome.webRequest;
  let mockTabs: typeof chrome.tabs;
  let cache: PermissionsPolicyHeaderCacheBackground;

  beforeEach(() => {
    onHeadersReceived = createMockEvent<HeadersListener>();
    onTabRemoved = createMockEvent<TabRemovedListener>();
    mockWebRequest = { onHeadersReceived } as unknown as typeof chrome.webRequest;
    mockTabs = { onRemoved: onTabRemoved } as unknown as typeof chrome.tabs;
    cache = new PermissionsPolicyHeaderCacheBackground(mockWebRequest, mockTabs);
  });

  function startAndCaptureListeners(): {
    headers: HeadersListener;
    tabRemoved: TabRemovedListener;
  } {
    cache.startListening();
    const headers = onHeadersReceived.addListener.mock.calls[0][0];
    const tabRemoved = onTabRemoved.addListener.mock.calls[0][0];
    return { headers, tabRemoved };
  }

  describe("startListening", () => {
    it("registers a webRequest.onHeadersReceived listener for main and sub-frame loads with responseHeaders", () => {
      cache.startListening();

      expect(onHeadersReceived.addListener).toHaveBeenCalledTimes(1);
      const [, filter, extraInfoSpec] = onHeadersReceived.addListener.mock.calls[0];
      expect(filter).toEqual({ urls: ["<all_urls>"], types: ["main_frame", "sub_frame"] });
      expect(extraInfoSpec).toEqual(["responseHeaders"]);
    });

    it("registers a tabs.onRemoved listener for cleanup", () => {
      cache.startListening();

      expect(onTabRemoved.addListener).toHaveBeenCalledTimes(1);
    });

    it("is idempotent", () => {
      cache.startListening();
      cache.startListening();

      expect(onHeadersReceived.addListener).toHaveBeenCalledTimes(1);
      expect(onTabRemoved.addListener).toHaveBeenCalledTimes(1);
    });
  });

  describe("stopListening", () => {
    it("removes both listeners", () => {
      cache.startListening();
      cache.stopListening();

      expect(onHeadersReceived.removeListener).toHaveBeenCalledTimes(1);
      expect(onTabRemoved.removeListener).toHaveBeenCalledTimes(1);
    });

    it("is safe to call without start", () => {
      expect(() => cache.stopListening()).not.toThrow();
      expect(onHeadersReceived.removeListener).not.toHaveBeenCalled();
    });

    it("allows restart after stop", () => {
      cache.startListening();
      cache.stopListening();
      cache.startListening();

      expect(onHeadersReceived.addListener).toHaveBeenCalledTimes(2);
    });
  });

  describe("recording headers", () => {
    it("stores a Permissions-Policy header keyed by (tabId, frameId)", () => {
      const { headers } = startAndCaptureListeners();

      headers(
        createDetails({
          tabId: 7,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "publickey-credentials-get=()" }],
        }),
      );

      expect(cache.getRawHeader(7, 0)).toBe("publickey-credentials-get=()");
    });

    it("matches header name case-insensitively", () => {
      const { headers } = startAndCaptureListeners();

      headers(
        createDetails({
          tabId: 7,
          frameId: 1,
          responseHeaders: [
            { name: "permissions-policy", value: "publickey-credentials-create=*" },
          ],
        }),
      );

      expect(cache.getRawHeader(7, 1)).toBe("publickey-credentials-create=*");
    });

    it("joins multiple Permissions-Policy headers with `, ` (per RFC 8941)", () => {
      const { headers } = startAndCaptureListeners();

      headers(
        createDetails({
          tabId: 1,
          frameId: 0,
          responseHeaders: [
            { name: "Permissions-Policy", value: "publickey-credentials-get=()" },
            { name: "Permissions-Policy", value: "publickey-credentials-create=()" },
          ],
        }),
      );

      expect(cache.getRawHeader(1, 0)).toBe(
        "publickey-credentials-get=(), publickey-credentials-create=()",
      );
    });

    it("ignores other response headers", () => {
      const { headers } = startAndCaptureListeners();

      headers(
        createDetails({
          tabId: 1,
          frameId: 0,
          responseHeaders: [
            { name: "Content-Type", value: "text/html" },
            { name: "X-Frame-Options", value: "DENY" },
          ],
        }),
      );

      expect(cache.getRawHeader(1, 0)).toBeUndefined();
    });

    it("skips entries for non-tab requests (tabId < 0)", () => {
      const { headers } = startAndCaptureListeners();

      headers(
        createDetails({
          tabId: -1,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "x=()" }],
        }),
      );

      expect(cache.size()).toBe(0);
    });

    it("treats a header with empty/missing value as no header", () => {
      const { headers } = startAndCaptureListeners();

      headers(
        createDetails({
          tabId: 1,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "" }],
        }),
      );

      expect(cache.getRawHeader(1, 0)).toBeUndefined();
    });

    it("clears a stale entry when a fresh response has no Permissions-Policy header", () => {
      const { headers } = startAndCaptureListeners();
      headers(
        createDetails({
          tabId: 1,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "x=()" }],
        }),
      );
      expect(cache.getRawHeader(1, 0)).toBe("x=()");

      headers(createDetails({ tabId: 1, frameId: 0, responseHeaders: [] }));

      expect(cache.getRawHeader(1, 0)).toBeUndefined();
    });

    it("overwrites the entry when a fresh response brings a new Permissions-Policy header", () => {
      const { headers } = startAndCaptureListeners();
      headers(
        createDetails({
          tabId: 1,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "x=()" }],
        }),
      );

      headers(
        createDetails({
          tabId: 1,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "y=*" }],
        }),
      );

      expect(cache.getRawHeader(1, 0)).toBe("y=*");
    });

    it("keys entries independently per (tabId, frameId)", () => {
      const { headers } = startAndCaptureListeners();
      headers(
        createDetails({
          tabId: 1,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "a=()" }],
        }),
      );
      headers(
        createDetails({
          tabId: 1,
          frameId: 5,
          responseHeaders: [{ name: "Permissions-Policy", value: "b=()" }],
        }),
      );
      headers(
        createDetails({
          tabId: 2,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "c=()" }],
        }),
      );

      expect(cache.getRawHeader(1, 0)).toBe("a=()");
      expect(cache.getRawHeader(1, 5)).toBe("b=()");
      expect(cache.getRawHeader(2, 0)).toBe("c=()");
    });
  });

  describe("tab removal", () => {
    it("clears every cached entry for the removed tab", () => {
      const { headers, tabRemoved } = startAndCaptureListeners();
      headers(
        createDetails({
          tabId: 1,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "a=()" }],
        }),
      );
      headers(
        createDetails({
          tabId: 1,
          frameId: 5,
          responseHeaders: [{ name: "Permissions-Policy", value: "b=()" }],
        }),
      );
      headers(
        createDetails({
          tabId: 2,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "c=()" }],
        }),
      );

      tabRemoved(1);

      expect(cache.getRawHeader(1, 0)).toBeUndefined();
      expect(cache.getRawHeader(1, 5)).toBeUndefined();
      expect(cache.getRawHeader(2, 0)).toBe("c=()");
    });

    it("does not clear similar-prefixed tab IDs (no `10:` from a `1:` removal)", () => {
      const { headers, tabRemoved } = startAndCaptureListeners();
      headers(
        createDetails({
          tabId: 1,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "a=()" }],
        }),
      );
      headers(
        createDetails({
          tabId: 10,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "b=()" }],
        }),
      );

      tabRemoved(1);

      expect(cache.getRawHeader(1, 0)).toBeUndefined();
      expect(cache.getRawHeader(10, 0)).toBe("b=()");
    });
  });

  describe("invalidate", () => {
    it("drops a specific (tabId, frameId) entry", () => {
      const { headers } = startAndCaptureListeners();
      headers(
        createDetails({
          tabId: 1,
          frameId: 0,
          responseHeaders: [{ name: "Permissions-Policy", value: "a=()" }],
        }),
      );

      cache.invalidate(1, 0);

      expect(cache.getRawHeader(1, 0)).toBeUndefined();
    });
  });
});

import { IframeAllowAttribute } from "../../content/iframe-allow-scraper";

import { IframeAllowCacheBackground } from "./iframe-allow-cache.background";

type TabRemovedListener = (tabId: number) => void;

interface MockEvent<L> {
  addListener: jest.Mock<void, [L]>;
  removeListener: jest.Mock<void, [L]>;
}

function createMockEvent<L>(): MockEvent<L> {
  return { addListener: jest.fn(), removeListener: jest.fn() };
}

function entry(src: string, allow: string, srcdoc = false): IframeAllowAttribute {
  return { src, allow, srcdoc };
}

describe("IframeAllowCacheBackground", () => {
  let onTabRemoved: MockEvent<TabRemovedListener>;
  let mockTabs: typeof chrome.tabs;
  let cache: IframeAllowCacheBackground;

  beforeEach(() => {
    onTabRemoved = createMockEvent<TabRemovedListener>();
    mockTabs = { onRemoved: onTabRemoved } as unknown as typeof chrome.tabs;
    cache = new IframeAllowCacheBackground(mockTabs);
  });

  describe("startListening / stopListening", () => {
    it("registers a tabs.onRemoved listener", () => {
      cache.startListening();
      expect(onTabRemoved.addListener).toHaveBeenCalledTimes(1);
    });

    it("is idempotent", () => {
      cache.startListening();
      cache.startListening();
      expect(onTabRemoved.addListener).toHaveBeenCalledTimes(1);
    });

    it("stopListening removes the listener", () => {
      cache.startListening();
      cache.stopListening();
      expect(onTabRemoved.removeListener).toHaveBeenCalledTimes(1);
    });

    it("stopListening is safe to call before start", () => {
      expect(() => cache.stopListening()).not.toThrow();
      expect(onTabRemoved.removeListener).not.toHaveBeenCalled();
    });
  });

  describe("recording reports", () => {
    it("stores a report keyed by (tabId, parentFrameId)", () => {
      cache.recordReport(7, 0, [entry("https://child.example/", "publickey-credentials-get")]);

      expect(cache.getAllowForChildFrame(7, 0, "https://child.example/")).toBe(
        "publickey-credentials-get",
      );
    });

    it("overwrites a prior report for the same (tabId, parentFrameId)", () => {
      cache.recordReport(1, 0, [entry("https://a.example/", "a")]);
      cache.recordReport(1, 0, [entry("https://b.example/", "b")]);

      expect(cache.getAllowForChildFrame(1, 0, "https://a.example/")).toBeUndefined();
      expect(cache.getAllowForChildFrame(1, 0, "https://b.example/")).toBe("b");
    });

    it("keys reports independently per (tabId, parentFrameId)", () => {
      cache.recordReport(1, 0, [entry("https://a.example/", "a")]);
      cache.recordReport(1, 5, [entry("https://b.example/", "b")]);
      cache.recordReport(2, 0, [entry("https://c.example/", "c")]);

      expect(cache.getAllowForChildFrame(1, 0, "https://a.example/")).toBe("a");
      expect(cache.getAllowForChildFrame(1, 5, "https://b.example/")).toBe("b");
      expect(cache.getAllowForChildFrame(2, 0, "https://c.example/")).toBe("c");
    });

    it("skips entries for non-tab requests (tabId < 0)", () => {
      cache.recordReport(-1, 0, [entry("https://x.example/", "x")]);
      expect(cache.size()).toBe(0);
    });

    it("stores an empty report (useful as a 'parent has been heard from' marker)", () => {
      cache.recordReport(1, 0, []);
      expect(cache.size()).toBe(1);
      // Still nothing to find.
      expect(cache.getAllowForChildFrame(1, 0, "https://anywhere.example/")).toBeUndefined();
    });
  });

  describe("getAllowForChildFrame", () => {
    it("returns undefined when no parent report is cached", () => {
      expect(cache.getAllowForChildFrame(1, 0, "https://child.example/")).toBeUndefined();
    });

    it("returns undefined when no iframe in the report matches the child URL", () => {
      cache.recordReport(1, 0, [entry("https://a.example/", "a")]);

      expect(cache.getAllowForChildFrame(1, 0, "https://b.example/")).toBeUndefined();
    });

    it("returns the matching iframe's allow attribute", () => {
      cache.recordReport(1, 0, [
        entry("https://a.example/", "publickey-credentials-create"),
        entry("https://b.example/", "publickey-credentials-get"),
      ]);

      expect(cache.getAllowForChildFrame(1, 0, "https://b.example/")).toBe(
        "publickey-credentials-get",
      );
    });

    it("returns undefined when the matching iframe has an empty allow attribute", () => {
      cache.recordReport(1, 0, [entry("https://a.example/", "")]);

      expect(cache.getAllowForChildFrame(1, 0, "https://a.example/")).toBeUndefined();
    });

    it("does not match srcdoc iframes (no URL to match on)", () => {
      cache.recordReport(1, 0, [entry("", "publickey-credentials-get", true)]);

      expect(cache.getAllowForChildFrame(1, 0, "")).toBeUndefined();
      expect(cache.getAllowForChildFrame(1, 0, "about:srcdoc")).toBeUndefined();
    });

    it("returns the first match when multiple iframes share a src URL", () => {
      cache.recordReport(1, 0, [
        entry("https://a.example/", "first"),
        entry("https://a.example/", "second"),
      ]);

      expect(cache.getAllowForChildFrame(1, 0, "https://a.example/")).toBe("first");
    });

    describe("origin-level fallback (handles redirects / URL normalization)", () => {
      it("matches by origin when the frame URL differs from iframe.src by a trailing slash after 301", () => {
        cache.recordReport(1, 0, [
          entry("http://x.example:8081/foo?q=1", "publickey-credentials-get"),
        ]);

        expect(cache.getAllowForChildFrame(1, 0, "http://x.example:8081/foo/?q=1")).toBe(
          "publickey-credentials-get",
        );
      });

      it("matches by origin when the frame URL has a different path than iframe.src", () => {
        cache.recordReport(1, 0, [
          entry("https://a.example/entry", "publickey-credentials-create"),
        ]);

        expect(cache.getAllowForChildFrame(1, 0, "https://a.example/after-redirect")).toBe(
          "publickey-credentials-create",
        );
      });

      it("does not match when only the scheme differs (origins are distinct)", () => {
        cache.recordReport(1, 0, [entry("http://a.example/", "a")]);

        expect(cache.getAllowForChildFrame(1, 0, "https://a.example/")).toBeUndefined();
      });

      it("does not match when only the port differs (origins are distinct)", () => {
        cache.recordReport(1, 0, [entry("http://a.example:8080/", "a")]);

        expect(cache.getAllowForChildFrame(1, 0, "http://a.example:8081/")).toBeUndefined();
      });

      it("prefers the exact-URL match over the origin fallback", () => {
        cache.recordReport(1, 0, [
          entry("https://a.example/first", "first"),
          entry("https://a.example/exact", "exact"),
        ]);

        expect(cache.getAllowForChildFrame(1, 0, "https://a.example/exact")).toBe("exact");
      });

      it("returns undefined when childUrl is unparseable (e.g. about:srcdoc)", () => {
        cache.recordReport(1, 0, [entry("https://a.example/", "a")]);

        expect(cache.getAllowForChildFrame(1, 0, "about:srcdoc")).toBeUndefined();
      });
    });
  });

  describe("tab removal", () => {
    it("clears every report for the removed tab", () => {
      cache.startListening();
      const tabRemoved = onTabRemoved.addListener.mock.calls[0][0];

      cache.recordReport(1, 0, [entry("https://a.example/", "a")]);
      cache.recordReport(1, 5, [entry("https://b.example/", "b")]);
      cache.recordReport(2, 0, [entry("https://c.example/", "c")]);

      tabRemoved(1);

      expect(cache.getAllowForChildFrame(1, 0, "https://a.example/")).toBeUndefined();
      expect(cache.getAllowForChildFrame(1, 5, "https://b.example/")).toBeUndefined();
      expect(cache.getAllowForChildFrame(2, 0, "https://c.example/")).toBe("c");
    });

    it("doesn't clear similar-prefixed tab IDs (no `10:` from a `1:` removal)", () => {
      cache.startListening();
      const tabRemoved = onTabRemoved.addListener.mock.calls[0][0];

      cache.recordReport(1, 0, [entry("https://a.example/", "a")]);
      cache.recordReport(10, 0, [entry("https://b.example/", "b")]);

      tabRemoved(1);

      expect(cache.getAllowForChildFrame(1, 0, "https://a.example/")).toBeUndefined();
      expect(cache.getAllowForChildFrame(10, 0, "https://b.example/")).toBe("b");
    });
  });

  describe("invalidate", () => {
    it("drops a specific (tabId, parentFrameId) entry", () => {
      cache.recordReport(1, 0, [entry("https://a.example/", "a")]);

      cache.invalidate(1, 0);

      expect(cache.getAllowForChildFrame(1, 0, "https://a.example/")).toBeUndefined();
    });
  });
});

import { TestBed } from "@angular/core/testing";
import { mock, MockProxy } from "jest-mock-extended";
import { BehaviorSubject } from "rxjs";

import { ViewCacheService } from "@bitwarden/angular/platform/view-cache";
import { ConfigService } from "@bitwarden/common/platform/abstractions/config/config.service";

import {
  TwoFactorAuthEmailComponentCache,
  TwoFactorAuthEmailComponentCacheService,
} from "./two-factor-auth-email-component-cache.service";

describe("TwoFactorAuthEmailComponentCache", () => {
  describe("fromJSON", () => {
    it("returns null when input is null", () => {
      const result = TwoFactorAuthEmailComponentCache.fromJSON(null as any);
      expect(result).toBeNull();
    });

    it("creates a TwoFactorAuthEmailCache instance from valid JSON", () => {
      const jsonData = { emailSent: true };
      const result = TwoFactorAuthEmailComponentCache.fromJSON(jsonData);

      expect(result).not.toBeNull();
      expect(result).toBeInstanceOf(TwoFactorAuthEmailComponentCache);
      expect(result?.emailSent).toBe(true);
    });
  });
});

describe("TwoFactorAuthEmailComponentCacheService", () => {
  let service: TwoFactorAuthEmailComponentCacheService;
  let mockViewCacheService: MockProxy<ViewCacheService>;
  let mockConfigService: MockProxy<ConfigService>;
  let cacheData: BehaviorSubject<TwoFactorAuthEmailComponentCache | null>;
  let mockSignal: any;

  beforeEach(() => {
    mockViewCacheService = mock<ViewCacheService>();
    mockConfigService = mock<ConfigService>();
    cacheData = new BehaviorSubject<TwoFactorAuthEmailComponentCache | null>(null);
    mockSignal = jest.fn(() => cacheData.getValue());
    mockSignal.set = jest.fn((value: TwoFactorAuthEmailComponentCache | null) =>
      cacheData.next(value),
    );
    mockViewCacheService.signal.mockReturnValue(mockSignal);

    TestBed.configureTestingModule({
      providers: [
        TwoFactorAuthEmailComponentCacheService,
        { provide: ViewCacheService, useValue: mockViewCacheService },
        { provide: ConfigService, useValue: mockConfigService },
      ],
    });

    service = TestBed.inject(TwoFactorAuthEmailComponentCacheService);
  });

  it("creates the service", () => {
    expect(service).toBeTruthy();
  });

  describe("cacheData", () => {
    it("caches email sent state", () => {
      service.cacheData({ emailSent: true });

      expect(mockSignal.set).toHaveBeenCalledWith({
        emailSent: true,
      });
    });
  });

  describe("clearCachedData", () => {
    it("clears cached data", () => {
      service.clearCachedData();

      expect(mockSignal.set).toHaveBeenCalledWith(null);
    });
  });

  describe("getCachedData", () => {
    it("returns cached data", () => {
      const testData = new TwoFactorAuthEmailComponentCache();
      testData.emailSent = true;
      cacheData.next(testData);

      const result = service.getCachedData();

      expect(result).toEqual(testData);
      expect(mockSignal).toHaveBeenCalled();
    });
  });
});

