import { Jsonify } from "type-fest";

import { CipherPermissions as SdkCipherPermissions } from "@bitwarden/sdk-internal";

import { BaseResponse } from "../../../models/response/base.response";

export class CipherPermissionsApi extends BaseResponse implements SdkCipherPermissions {
  delete: boolean = false;
  restore: boolean = false;

  constructor(data: any = null) {
    super(data);
    if (data == null) {
      return;
    }
    this.delete = this.getResponseProperty("Delete");
    this.restore = this.getResponseProperty("Restore");
  }

  static fromJSON(obj: Jsonify<CipherPermissionsApi>) {
    return Object.assign(new CipherPermissionsApi(), obj);
  }

  /**
   * Converts the SDK CipherPermissionsApi to a CipherPermissionsApi.
   */
  static fromSdkCipherPermissions(
    obj: SdkCipherPermissions | undefined,
  ): CipherPermissionsApi | undefined {
    if (!obj) {
      return undefined;
    }

    const permissions = new CipherPermissionsApi();
    permissions.delete = obj.delete;
    permissions.restore = obj.restore;

    return permissions;
  }

  /**
   * Converts the CipherPermissionsApi to an SdkCipherPermissions
   */
  toSdkCipherPermissions(): SdkCipherPermissions {
    return this;
  }
}

import { Theme } from "@bitwarden/common/platform/enums";

import { BadgeButton } from "../../../content/components/buttons/badge-button";
import { EditButton } from "../../../content/components/buttons/edit-button";
import { NotificationTypes } from "../../../notification/abstractions/notification-bar";
import { I18n } from "../common-types";
import { selectedCipher as selectedCipherSignal } from "../signals/selected-cipher";

export type CipherActionProps = {
  cipherId: string;
  handleAction?: (e: Event) => void;
  i18n: I18n;
  itemName: string;
  notificationType: typeof NotificationTypes.Change | typeof NotificationTypes.Add;
  theme: Theme;
  username?: string;
};

export function CipherAction({
  cipherId,
  handleAction = () => {
    /* no-op */
  },
  i18n,
  itemName,
  notificationType,
  theme,
  username,
}: CipherActionProps) {
  const selectCipherHandleAction = (e: Event) => {
    selectedCipherSignal.set(cipherId);
    try {
      handleAction(e);
    } finally {
      selectedCipherSignal.set(null);
    }
  };
  return notificationType === NotificationTypes.Change
    ? BadgeButton({
        buttonAction: selectCipherHandleAction,
        buttonText: i18n.notificationUpdate,
        itemName,
        theme,
        username,
      })
    : EditButton({
        buttonAction: handleAction,
        buttonText: i18n.notificationEditTooltip,
        theme,
      });
}
